mapper.delete:
DELETE FROM artwork_images 
WHERE artwork_id = #{currentDraftArtWorkId} 
  AND file_url = #{fordName} 
  AND file_name = #{fileName};

mapper.select:
SELECT *
FROM artwork_comment
WHERE parent_comment_id IS NULL AND artwork_id = #{artworkId}
ORDER BY artwork_comment_id
LIMIT #{limit} OFFSET #{offset}

SELECT created_at
FROM artworks
WHERE created_at BETWEEN #{startOfWeek} AND #{endOfWeek}
